package app.unifeed.chat;
import java.util.List; import org.springframework.context.annotation.Configuration; import org.springframework.messaging.Message; import org.springframework.messaging.MessageChannel; import org.springframework.messaging.MessagingException; import org.springframework.messaging.simp.config.ChannelRegistration; import org.springframework.messaging.simp.config.MessageBrokerRegistry; import org.springframework.messaging.simp.stomp.*; import org.springframework.messaging.support.ChannelInterceptor; import org.springframework.messaging.support.MessageHeaderAccessor; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.oauth2.jwt.JwtDecoder; import org.springframework.web.socket.config.annotation.*;
@Configuration @EnableWebSocketMessageBroker public class WebSocketConfig implements WebSocketMessageBrokerConfigurer {
 private final JwtDecoder decoder; public WebSocketConfig(JwtDecoder d){decoder=d;}
 public void registerStompEndpoints(StompEndpointRegistry r){r.addEndpoint("/ws").setAllowedOriginPatterns("*").withSockJS();}
 public void configureMessageBroker(MessageBrokerRegistry r){r.enableSimpleBroker("/topic","/queue");r.setApplicationDestinationPrefixes("/app");r.setUserDestinationPrefix("/user");}
 public void configureClientInboundChannel(ChannelRegistration r){r.interceptors(new ChannelInterceptor(){public Message<?> preSend(Message<?> m,MessageChannel c){StompHeaderAccessor a=MessageHeaderAccessor.getAccessor(m,StompHeaderAccessor.class);if(a!=null&&StompCommand.CONNECT.equals(a.getCommand())){String h=a.getFirstNativeHeader("Authorization");if(h==null||!h.startsWith("Bearer "))throw new MessagingException("Missing bearer token");var jwt=decoder.decode(h.substring(7));a.setUser(new UsernamePasswordAuthenticationToken(jwt.getSubject(),null,List.of()));}return m;}});}
}
